para.verbatim:
double twoGamE2 = 2*GamE2;
double auxBetY = (1./GamE2) + Btx*Btx + Btz*Btz;
TVector3d vBet(Btx, 1. - 0.5*auxBetY - 0.125*auxBetY*auxBetY, Btz), vN(Nx, Ny, Nz);
TVector3d vBetPr(InvRx, -Btx*InvRx + Btz*InvRz, -InvRz), vN_mi_Bet = vN - vBet;
TVector3d vA = (twoGamE2*(vN^(vN_mi_Bet^vBetPr))) + ((2.*invRinst)*vN_mi_Bet);

inbodydescription.para:
TVector3d vA = (twoGamE2*(vN^(vN_mi_Bet^vBetPr))); //OC TEST*********************         double InvOne_p_GamBtE2 = 1./(twoGamE2*(1. - (vN*vBet)));
        double ComFact = invRinst*invRinst*InvOne_p_GamBtE2*InvOne_p_GamBtE2*InvOne_p_GamBtE2*InvOne_p_GamBtE2*InvOne_p_GamBtE2;
        double ComFact2 = ComFact*invRinst/(GamE2*InvOne_p_GamBtE2);
        double ComFact_cosFactProj = ComFact*cosFactProj;

        double half_vAe2 = 0.5*vA.y*vA.y;
 OC TEST********************* To uncomment here! Fx = ComFact_cosFactProj*(vA.x*vA.x + half_vAe2); //artificial trick: adding longitudinal component to transverse ones Fz = ComFact_cosFactProj*(vA.z*vA.z + half_vAe2); OC TEST********************* Fx = ::fabs(ComFact_cosFactProj*(vA.x*vA.x)); //artificial trick: adding longitudinal component to transverse ones Fz = ::fabs(ComFact_cosFactProj*(vA.z*vA.z)); END TEST         double half_scalProdY = 0.5*vEyP_y*vA.y;
 OC TEST********************* To uncomment here! Fx = ::fabs(Fx - ComFact2*(vEyP_x*vA.x + half_scalProdY)); Fz = ::fabs(Fz - ComFact2*(vEyP_z*vA.z + half_scalProdY));
